presets.css:
/* Puff · 淡黄可爱主题（基于短模板改色） */

.chat-thread {
  --dress-chat-bg-overlay: transparent;
}

/* 顶栏胶囊 */
.chat-thread-pill {
  background: rgba(255, 249, 219, 0.94);
  border: 1px solid rgba(230, 200, 110, 0.35);
  border-radius: 22px;
  box-shadow: 0 6px 18px rgba(214, 178, 80, 0.16);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  color: #b89a4a;
}
.chat-thread-center h2 {
  color: #6b5a2e;
  font-size: 15px;
  font-weight: 600;
}
.chat-thread-pill .chat-back,
.chat-thread-head-more,
.chat-thread-head-xinsheng {
  color: #b89a4a;
  background: transparent;
}

/* 昵称 / 时间 */
.chat-msg-name {
  font-size: 11px;
  color: #b8a46a;
  opacity: 0.9;
}
.chat-msg-timestamp,
.chat-thread-notice {
  color: #b8a46a;
}

/* 对方气泡 */
.chat-msg.is-them .chat-bubble {
  background: #fffdf2;
  color: #5a4a22;
  border: 1px solid rgba(235, 215, 150, 0.55);
  border-radius: 18px;
  border-bottom-left-radius: 6px;
  box-shadow: 0 2px 10px rgba(214, 178, 80, 0.10);
}
/* 我方气泡 */
.chat-msg.is-me .chat-bubble {
  background: #fff3b8;
  color: #5a4a22;
  border: 1px solid rgba(235, 205, 120, 0.55);
  border-radius: 18px;
  border-bottom-right-radius: 6px;
  box-shadow: 0 2px 8px rgba(214, 178, 80, 0.12);
}
.chat-bubble-primary {
  line-height: 1.6;
}

/* 引用块 */
.chat-qq-quote {
  background: rgba(255, 243, 184, 0.55);
  border-left: 3px solid #e8c860;
  border-radius: 8px;
  opacity: 1;
}
.chat-qq-quote-name {
  font-size: 11px;
  color: #b89a4a;
  opacity: 1;
}
.chat-qq-quote-text {
  font-size: 12px;
  color: #8a7a4a;
}

/* 转账卡片 */
.puff-transfer {
  background: #fffdf2;
  border: 1px solid rgba(235, 215, 150, 0.55);
  border-radius: 14px;
}
.puff-transfer-badge {
  background: rgba(245, 215, 110, 0.30);
}
.puff-transfer-k {
  color: #b89a4a;
}

/* 语音条 */
.chat-msg.is-them .puff-voice-pill {
  background: #fffdf2;
  color: #5a4a22;
  border: 1px solid rgba(235, 215, 150, 0.55);
  border-radius: 999px;
  box-shadow: 0 2px 10px rgba(214, 178, 80, 0.10);
}
.chat-msg.is-me .puff-voice-pill {
  background: #fff3b8;
  color: #5a4a22;
  border: 1px solid rgba(235, 205, 120, 0.55);
  border-radius: 999px;
  box-shadow: 0 2px 8px rgba(214, 178, 80, 0.12);
}

/* 翻译展开 */
.chat-bubble-trans-inline,
.chat-bubble-trans-chip {
  opacity: 0.9;
}
.chat-bubble-trans-chip-label {
  font-size: 10px;
  color: #b89a4a;
  opacity: 1;
}

/* 推演 */
.chat-thinking-chip {
  background: rgba(255, 243, 184, 0.70);
  color: #b89a4a;
  border: 1px solid rgba(235, 205, 120, 0.50);
  border-radius: 999px;
  padding: 2px 10px;
  font-size: 11px;
}

/* ===== 输入胶囊 ===== */
.chat-compose-bar {
  background: rgba(255, 249, 219, 0.94);
  color: #5a4a22;
  border: 1px solid rgba(230, 200, 110, 0.40);
  border-radius: 24px;
  box-shadow: 0 8px 24px rgba(214, 178, 80, 0.16);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}
/* 按钮颜色：保证可见 */
.chat-compose-plus {
  color: #b89a4a;
  background: transparent;
}
.chat-compose-icon.is-voice,
.chat-compose-icon.is-reply {
  color: #b89a4a;
}
.chat-compose-icon.is-send.ready {
  background: #f5d76e;
  color: #6b5a2e;
  border-radius: 50%;
}
.chat-compose-input {
  color: #5a4a22;
}
.chat-compose-input::placeholder {
  color: #c8b070;
}

/* ===== 深色模式 ===== */
html[data-theme="dark"] .chat-thread-pill {
  background: rgba(58, 50, 28, 0.94);
  border-color: rgba(200, 170, 90, 0.25);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
  color: #e0c878;
}
html[data-theme="dark"] .chat-thread-center h2 { color: #f5e6b8; }
html[data-theme="dark"] .chat-thread-pill .chat-back,
html[data-theme="dark"] .chat-thread-head-more,
html[data-theme="dark"] .chat-thread-head-xinsheng {
  color: #e0c878;
}
html[data-theme="dark"] .chat-msg.is-them .chat-bubble {
  background: #3d3520;
  color: #f0e6c0;
  border-color: rgba(200, 170, 90, 0.20);
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.28);
}
html[data-theme="dark"] .chat-msg.is-me .chat-bubble {
  background: #6b5a2e;
  color: #fff3b8;
  border-color: rgba(200, 170, 90, 0.35);
}
html[data-theme="dark"] .chat-msg-name,
html[data-theme="dark"] .chat-msg-timestamp,
html[data-theme="dark"] .chat-thread-notice {
  color: #d8c890;
}
html[data-theme="dark"] .chat-compose-bar {
  background: rgba(58, 50, 28, 0.94);
  border-color: rgba(200, 170, 90, 0.25);
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.35);
}
html[data-theme="dark"] .chat-compose-input { color: #f5e6b8; }
html[data-theme="dark"] .chat-compose-plus,
html[data-theme="dark"] .chat-compose-icon.is-voice,
html[data-theme="dark"] .chat-compose-icon.is-reply {
  color: #e0c878;
}
html[data-theme="dark"] .chat-compose-icon.is-send.ready {
  background: #c8a850;
  color: #3d3520;
}
